5	/**
6	 * Normalizes telephone numbers to E.164 form.
7	 *
8	 * <p>Spaces, dashes and brackets are stripped. When a leading {@code '+'} (an explicit
9	 * country code) is present it is kept as-is; otherwise country code {@code '+61'} is
10	 * assumed and a single leading {@code '0'} is dropped from the national digits. The
11	 * result must be {@code '+'} followed by 8 to 15 digits, else it cannot form a valid
12	 * E.164 number.
13	 *
14	 * <p>For a recognised country code the national number (the digits after the code) must
15	 * also be exactly the length that country uses: {@code '+61'} requires 9 national digits
16	 * and {@code '+1'} requires 10. A wrong length yields {@code null}. Country codes not
17	 * listed fall back to the generic 8-to-15 total-digit rule.
18	 *
19	 * <p>E.g. {@code "0412 345 678"} -> {@code "+61412345678"} and
20	 * {@code "+64 21 123 456"} -> {@code "+6421123456"}.
21	 */
22	public final class Telephones {
23	
24	    /** Recognised country code (without the {@code '+'}) -> required national-number length. */
25	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of(
26	            "61", 9,
27	            "1", 10);
28	
29	    private Telephones() {
30	    }
31	
32	    /**
33	     * Converts a telephone number to its E.164 form, or returns {@code null} when the
34	     * input cannot form a valid E.164 number.
35	     */
36	    public static String toE164(String telephone) {
37	        if (telephone == null) {
38	            return null;
39	        }
40	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
41	        String digits;
42	        if (cleaned.startsWith("+")) {
43	            digits = cleaned.substring(1);
44	        }
45	        else {
46	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
47	            digits = "61" + national;
48	        }
49	        if (!digits.matches("\\d{8,15}")) {
50	            return null;
51	        }
52	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
53	            String code = country.getKey();
54	            if (digits.startsWith(code)) {
55	                return digits.length() - code.length() == country.getValue() ? "+" + digits : null;
56	            }
57	        }
58	        return "+" + digits;
59	    }
60	
61	    /**
62	     * Formats a stored telephone number for humans: the country code, a space, then the
63	     * national digits grouped in threes (e.g. {@code "+61412345678"} ->
64	     * {@code "+61 412 345 678"}). The input is first normalized via {@link #toE164};
65	     * when it cannot form a valid E.164 number {@code null} is returned.
66	     *
67	     * <p>For a recognised country code the code is split off first so it stays intact;
68	     * otherwise the digits after the {@code '+'} are grouped in threes as a whole.
69	     */
70	    public static String toDisplay(String telephone) {
71	        String e164 = toE164(telephone);
72	        if (e164 == null) {
73	            return null;
74	        }
75	        String digits = e164.substring(1);
76	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
77	            String code = country.getKey();
78	            if (digits.startsWith(code) && digits.length() - code.length() == country.getValue()) {
79	                return "+" + code + " " + groupInThrees(digits.substring(code.length()));
80	            }
81	        }
82	        return "+" + groupInThrees(digits);
83	    }
84	
85	    /** Groups digits into space-separated runs of three, from the left. */
86	    private static String groupInThrees(String digits) {
87	        StringBuilder grouped = new StringBuilder();
88	        for (int i = 0; i < digits.length(); i++) {
89	            if (i > 0 && i % 3 == 0) {
90	                grouped.append(' ');
91	            }
92	            grouped.append(digits.charAt(i));
93	        }
94	        return grouped.toString();
95	    }
96	}
